/* Carregar depois de galeria.js e antes de script.js. */
(() => {
  const media = window.matchMedia('(max-width: 780px)');
  function scaleMobile(){ document.documentElement.style.setProperty('--mobile-scale', document.documentElement.clientWidth / 393); }
  scaleMobile(); window.addEventListener('resize', scaleMobile, {passive:true});
  const title = document.querySelector('.hero h1');
  title.innerHTML = 'Manual dos<span class="mobile-break"> </span>Padrinhos';
  const dress = document.getElementById('dress-title');
  dress.innerHTML = '<span class="dress-title-desktop">'+dress.textContent+'</span><span class="dress-title-mobile">Dress code dos<br>Padrinhos</span>';
  const composition = document.querySelectorAll('.composition-copy p');
  composition[0].innerHTML = composition[0].innerHTML.replace(' Pensem em ', ' <span class="mobile-paragraph">Pensem em ') + '</span>';
  composition[1].innerHTML = composition[1].innerHTML.replace('<br>', '<br><span class="mobile-paragraph">') + '</span>';
  const end = document.querySelector('.ending .section-heading');
  end.innerHTML = 'Nos vemos no<span class="mobile-break"> </span>grande dia!';
  // Foto inicial do PDF mobile; os outros quatro itens e os controles continuam ativos.
  const firstPhoto = window.MANUAL_GALLERY?.[0];
  if(firstPhoto){
    const desktopSrc = firstPhoto.src, desktopAlt = firstPhoto.alt;
    const mobileSrc = 'data:image/webp;base64,';
    Object.defineProperties(firstPhoto, {
      src:{get:()=>media.matches?mobileSrc:desktopSrc, configurable:true},
      alt:{get:()=>media.matches?'Vista da praia e do píer de São Tomé':desktopAlt, configurable:true}
    });
    media.addEventListener('change',()=>document.querySelector('.gallery-dot.active')?.click());
  }
})();
